function grab(start, end) {
  const i = norm.indexOf(start), j = norm.indexOf(end, i);
  if (i < 0 || j < 0) throw new Error("miss " + start.slice(0, 30));
  return norm.slice(i, j + end.length);
}
const items = [
  ["cyclone", 1, grab("The house whirled around two or three times", "as easily as you could carry a feather.")],
  ["kalidahs", 7, grab("They had just started to cross this queer bridge", "looked at him\nin surprise.")],
  ["poppy-field", 8, grab("They now came upon more and more of the big scarlet poppies", "fell among the poppies, fast asleep.")],
];
let src = "// Verbatim excerpts from Project Gutenberg #55 (The Wonderful Wizard of Oz,\n// public domain). 80 to 200 words each. Shared input for the spike scripts.\n\nexport const passages = [\n";
for (const [id, ch, text] of items) {
  const words = text.split(/\s+/).filter(Boolean).length;
  src += "  {\n    id: " + JSON.stringify(id) + ",\n    chapter: " + ch + ",\n    words: " + words + ",\n    text: " + JSON.stringify(text) + ",\n  },\n";
}
src += "];\n";
fs.writeFileSync("scripts/spikes/passages.mjs", src);
console.log("wrote", src.length, "bytes");
